const scores = { Alice: 95, Bob: 80, Charlie: 92 };

// 1. Destructured iteration
for (const [student, score] of Object.entries(scores)) {
  console.log(`${student}: ${score}`);
}

// 2. Filter object entries and rebuild
const topStudents = Object.fromEntries(
  Object.entries(scores).filter(([_, score]) => score >= 90)
);
console.log(topStudents); // { Alice: 95, Charlie: 92 }

// 3. Convert to Map
const scoresMap = new Map(Object.entries(scores));

