const source = {
  firstName: 'John',
  lastName: 'Doe',
  get fullName() {
    return `${this.firstName} ${this.lastName}`;
  }
};

// Object.assign evaluates the getter prematurely:
const badClone = Object.assign({}, source);
console.log(badClone.fullName); // "John Doe"
source.firstName = 'Jane';
console.log(badClone.fullName); // Still "John Doe" (getter was turned into static property!)

// True clone preserving getter accessors:
const goodClone = Object.defineProperties(
  {},
  Object.getOwnPropertyDescriptors(source)
);
goodClone.firstName = 'Jane';
console.log(goodClone.fullName); // "Jane Doe" (getter function was preserved!)

